/* ============================================================================
 * FILE 3 of 3:  js/srs/queue.js  — limits, burying, backlog, deck mixing
 * ========================================================================== */

import { FSRS, RATING, STATE, createEmptyCard } from './fsrs6.js';

export function dayKey(ts, dayStartHour = 4) {
  const d = new Date(ts - dayStartHour * 3600000);
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') +
         '-' + String(d.getDate()).padStart(2, '0');
}
export function nextDayStart(ts, dayStartHour = 4) {
  const d = new Date(ts); d.setHours(dayStartHour, 0, 0, 0);
  if (d.getTime() <= ts) d.setDate(d.getDate() + 1);
  return d.getTime();
}

/**
 * Build one merged study queue across all active decks.
 * cards: array of card rows already loaded from IndexedDB (filter by active decks first).
 */
export function buildQueue(cards, opts) {
  const now = opts.now ?? Date.now();
  const { decks, settings, todayStats } = opts;          // decks: {N5:{newPerDay,...},...}
  const live = cards.filter(c =>
    !c.suspended && (!c.buriedUntil || c.buriedUntil <= now));

  // 1. Learning / relearning that is actually due — never limited, never deck-filtered.
  const learning = live
    .filter(c => (c.state === STATE.Learning || c.state === STATE.Relearning) && c.due <= now)
    .sort((a, b) => a.due - b.due);

  // 2. Reviews, oldest-due first, capped.
  const reviewCap = Math.max(0,
    (settings.maxReviewsPerDay ?? 200) - (todayStats.reviewsDone || 0));
  const allDueReviews = live
    .filter(c => c.state === STATE.Review && c.due <= now)
    .sort((a, b) => a.due - b.due);
  const reviews = opts.catchUp ? allDueReviews : allDueReviews.slice(0, reviewCap);

  // 3. New cards, per-deck budget.
  const newCards = [];
  for (const [deckId, cfg] of Object.entries(decks)) {
    if (!cfg.active || opts.catchUp) continue;
    const budget = Math.max(0, (cfg.newPerDay || 0) - (todayStats.newByDeck?.[deckId] || 0));
    if (!budget) continue;
    const pool = live
      .filter(c => c.state === STATE.New && c.decks.includes(deckId) && c.introducedAt)
      .sort((a, b) => (a.freqRank ?? 1e9) - (b.freqRank ?? 1e9));   // frequency order
    newCards.push(...pool.slice(0, budget));
  }

  // 4. Interleave: reviews are the spine, drop a new card in every `gap` positions.
  const queue = [...learning];
  const gap = newCards.length ? Math.max(3, Math.floor(reviews.length / (newCards.length + 1))) : 0;
  let ni = 0;
  reviews.forEach((c, i) => {
    queue.push(c);
    if (gap && (i + 1) % gap === 0 && ni < newCards.length) queue.push(newCards[ni++]);
  });
  while (ni < newCards.length) queue.push(newCards[ni++]);

  return {
    queue,
    counts: { learning: learning.length, review: reviews.length, new: newCards.length },
    backlog: Math.max(0, allDueReviews.length - reviews.length),
  };
}

/**
 * Answer one card. Returns everything the caller must persist, in one object.
 * Call inside a single IndexedDB readwrite txn over ['cards','reviewLogs','dayStats'].
 */
export function answerCard(card, rating, ctx) {
  const now = ctx.now ?? Date.now();
  const fsrs = new FSRS({
    request_retention: ctx.settings.requestRetention ?? 0.9,
    enable_fuzz:      ctx.settings.enableFuzz ?? true,
    learning_steps:   ctx.settings.learningSteps ?? ['1m', '10m'],
    relearning_steps: ctx.settings.relearningSteps ?? ['10m'],
    maximum_interval: ctx.settings.maximumInterval ?? 36500,
    enable_short_term: true,
  });

  const before = { ...card };
  const memIn = {
    due: new Date(card.due), stability: card.stability, difficulty: card.difficulty,
    elapsed_days: card.elapsed_days, scheduled_days: card.scheduled_days,
    reps: card.reps, lapses: card.lapses, learning_steps: card.learning_steps,
    state: card.state, last_review: card.last_review ? new Date(card.last_review) : null,
  };
  const { card: out, log } = fsrs.schedule(memIn, rating, new Date(now));

  let due = out.due.getTime();
  // optional load balancing for intervals >= 7 days
  if (ctx.settings.loadBalance && out.state === STATE.Review && out.scheduled_days >= 7 && ctx.dueCountByDay) {
    const span = Math.max(1, Math.round(out.scheduled_days * 0.15));
    let best = out.scheduled_days, bestN = Infinity;
    for (let d = out.scheduled_days - span; d <= out.scheduled_days + span; d++) {
      if (d < 1) continue;
      const k = dayKey(now + d * 86400000, ctx.settings.dayStartHour ?? 4);
      const n = ctx.dueCountByDay[k] || 0;
      if (n < bestN) { bestN = n; best = d; }
    }
    out.scheduled_days = best;
    due = now + best * 86400000;
  }

  const next = {
    ...card,
    due,
    stability: out.stability, difficulty: out.difficulty,
    elapsed_days: out.elapsed_days, scheduled_days: out.scheduled_days,
    reps: out.reps, lapses: out.lapses, learning_steps: out.learning_steps,
    state: out.state,
    last_review: out.last_review.getTime(),
    buriedUntil: 0,
  };

  // leech detection
  const threshold = ctx.settings.leechThreshold ?? 8;
  if (next.lapses >= threshold && !card.leech) next.leech = true;
  if (ctx.settings.autoSuspendAt && next.lapses >= ctx.settings.autoSuspendAt) next.suspended = true;

  // sibling burying
  const buryUntil = nextDayStart(now, ctx.settings.dayStartHour ?? 4);
  const buryIds = [];
  for (const sib of (ctx.siblings || [])) {
    if (sib.id === card.id || sib.suspended) continue;
    const isNew = sib.state === STATE.New;
    const wantBury =
      (isNew && ctx.settings.buryNewSiblings) ||
      (!isNew && ctx.settings.buryReviewSiblings);
    if (wantBury && (!sib.buriedUntil || sib.buriedUntil < buryUntil)) buryIds.push(sib.id);
  }

  const reviewLog = {
    cardId: card.id, noteId: card.noteId, deck: card.decks[0], cardType: card.cardType,
    rating, state: before.state,
    elapsedDays: log.elapsed_days, lastElapsedDays: log.last_elapsed_days,
    scheduledDays: before.scheduled_days,
    stabilityBefore: before.stability, difficultyBefore: before.difficulty,
    reviewedAt: now, durationMs: ctx.durationMs || 0, source: ctx.source || 'review',
  };

  return { next, before, reviewLog, buryIds, buryUntil };
}

/** Undo: restore the exact pre-review row and drop the log. Never invert the math. */
export function undo(entry, db) { /* put(entry.before); delete reviewLogs[entry.logId] */ }

/**
 * Seed a brand-new card from the FIRST-EXPOSURE ("learn words") mini-quiz.
 * Do NOT ask the learner Again/Hard/Good/Easy here — derive it.
 *   correctFirstTry && fastMs < 3000  -> Easy  (S0 = 8.2956d, skips learning steps)
 *   correctFirstTry                   -> Good  (S0 = 2.3065d)
 *   correct after peeking             -> Hard  (S0 = 1.2931d)
 *   wrong                             -> Again (S0 = 0.2120d)
 */
export function ratingFromFirstExposure({ correct, peeked, ms }) {
  if (!correct) return RATING.Again;
  if (peeked) return RATING.Hard;
  return ms < 3000 ? RATING.Easy : RATING.Good;
}

/** Label the four buttons with their real intervals before the tap. */
export function buttonLabels(card, settings, now = Date.now()) {
  const fsrs = new FSRS({
    request_retention: settings.requestRetention ?? 0.9,
    enable_fuzz: false,                       // preview unfuzzed so labels are stable
    learning_steps: settings.learningSteps ?? ['1m', '10m'],
    relearning_steps: settings.relearningSteps ?? ['10m'],
  });
  const memIn = { ...card, due: new Date(card.due),
                  last_review: card.last_review ? new Date(card.last_review) : null };
  const all = fsrs.repeat(memIn, new Date(now));
  const fmt = (c) => {
    const mins = (c.due.getTime() - now) / 60000;
    if (mins < 60)   return Math.round(mins) + 'm';
    if (mins < 1440) return Math.round(mins / 60) + 'h';
    const d = Math.round(mins / 1440);
    if (d < 31)  return d + 'd';
    if (d < 365) return (d / 30).toFixed(1) + 'mo';
    return (d / 365).toFixed(1) + 'y';
  };
  return { 1: fmt(all[1].card), 2: fmt(all[2].card), 3: fmt(all[3].card), 4: fmt(all[4].card) };
}


